--- /dev/null
+++ b/Umbraco.Bench.Umbraco/ViewComponents/BlogPostListViewComponent.cs
@@ -0,0 +1,32 @@
+using Microsoft.AspNetCore.Mvc;
+using Umbraco.Bench.Umbraco.Models;
+using Umbraco.Bench.Umbraco.Models.Blocks;
+using Umbraco.Cms.Core.Web;
+using Umbraco.Extensions;
+
+namespace Umbraco.Bench.Umbraco.ViewComponents;
+
+public sealed class BlogPostListViewComponent(IUmbracoContextAccessor umbracoContextAccessor) : ViewComponent
+{
+    public IViewComponentResult Invoke(BlogPostListModel model)
+    {
+        var posts = Array.Empty<BlogPostSummary>();
+
+        if (umbracoContextAccessor.TryGetUmbracoContext(out var umbracoContext) &&
+            umbracoContext.PublishedRequest?.PublishedContent is BlogLandingPage landingPage)
+        {
+            posts = landingPage.Children<BlogPost>()
+                .Select(post => new BlogPostSummary(
+                    post.Name,
+                    post.Url(),
+                    post.CreateDate.ToString("MMMM d, yyyy")))
+                .ToArray();
+        }
+
+        return View(new BlogPostListModel
+        {
+            Heading = model.Heading,
+            Posts = posts
+        });
+    }
+}
