@using Umbraco.Cms.Core.Models.Blocks
@using Umbraco.Bench.Umbraco.Models.Blocks
@inherits Umbraco.Cms.Web.Common.Views.UmbracoViewPage<BlockGridItem<HeroBlock>>
@{
    var model = new HeroModel
    {
        Heading = Model.Content.Heading ?? string.Empty,
        Intro = Model.Content.Intro ?? string.Empty,
        ImageUrl = Model.Content.Image?.GetCropUrl(width: 1800, height: 900)
    };
}
@await Component.InvokeAsync("Hero", new { model })

@using Umbraco.Cms.Core.Models.Blocks
@using Umbraco.Bench.Umbraco.Models.Blocks
@inherits Umbraco.Cms.Web.Common.Views.UmbracoViewPage<BlockGridItem<RichTextBlock>>
@{
    var model = new RichTextModel
    {
        Body = Model.Content.Body?.ToHtmlString() ?? string.Empty
    };
}
@await Component.InvokeAsync("RichText", new { model })

@model HeroModel
<section class="relative isolate overflow-hidden border-b border-white/10">
    @if (!string.IsNullOrWhiteSpace(Model.ImageUrl))
    {
        <img class="absolute inset-0 -z-10 h-full w-full object-cover opacity-30" src="@Model.ImageUrl" alt="" />
    }
    <div class="absolute inset-0 -z-10 bg-gradient-to-br from-slate-950 via-slate-950/90 to-cyan-950/60"></div>
    <div class="mx-auto max-w-6xl px-6 py-28 sm:py-40">
        <p class="mb-6 text-sm font-semibold tracking-[0.25em] text-cyan-300 uppercase">The MCP journal</p>
        <h1 class="max-w-4xl text-5xl font-semibold tracking-tight text-white sm:text-7xl">@Model.Heading</h1>
        <p class="mt-8 max-w-2xl text-lg leading-8 text-slate-300">@Model.Intro</p>
    </div>
</section>

@model RichTextModel
<section class="mx-auto max-w-3xl px-6 py-16">
    <div class="prose prose-invert prose-lg max-w-none leading-8 text-slate-300">
        @Html.Raw(Model.Body)
    </div>
</section>

